def kit(slug, title, cat, summary, why, role, context, output, examples, adapt, checks):
    return dict(slug=slug, title=title, cat=cat, summary=summary, why=why, role=role, context=context,
                output=output, examples=examples, adapt=adapt, checks=checks)

